__AETHER_CC_061__
root="$tmp/AetherForge-Control-Center-v0.6.1-InstallerSchema-Reforge"
inner="$root/INSTALL-AETHER-CONTROL-CENTER-v0.6.1.sh"
chmod +x "$inner"
case "${1:-}" in
  --self-test)
    bash "$inner" --self-test
    main="$root/apps/aether-control-center/src/main.rs"
    cargo="$root/apps/aether-control-center/Cargo.toml"
    ! grep -Fq 'include_image!' "$main"
    ! grep -Fq 'aether-control-center-background.png' "$main"
    grep -Fq 'fn installer_shell' "$main"
    grep -Fq 'fn experience_card' "$main"
    grep -Fq 'fn system_rail' "$main"
    grep -Fq 'fn bottom_action_strip' "$main"
    grep -Fq 'egui::Panel::left("aether-sidebar")' "$main"
    grep -Fq 'egui::Panel::right("system-rail")' "$main"
    grep -Fq 'fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame)' "$main"
    grep -Fq 'eframe = { version = "=0.35.0"' "$cargo"
    grep -Fq '0.6.1-installer-schema-reforge' "$inner"
    grep -Fq 'AETHER_CONTROL_CENTER_V0_6_1_INSTALL=COMPLETE' "$inner"
    echo 'AETHER_CONTROL_CENTER_V0_6_1_STANDALONE_SELF_TEST=PASS'
    ;;
  --install)
    [[ ${EUID:-$(id -u)} -ne 0 ]] || {
      echo 'ERROR: run this as your normal desktop user; sudo is handled internally.' >&2
      exit 2
    }
    exec bash "$inner" --install
    ;;
  *)
    echo "usage: $0 --self-test | --install" >&2
    exit 2
    ;;
esac
